package org.jtodd.ffm.ffmrmatrix;

import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Arrays;

import org.jtodd.ffm.JGaussFactorization;
import org.jtodd.ffm.JRashunalMatrix;
import org.jtodd.ffm.RMatrixFFM;

public class App {
    public static void main(String[] args) {
        int [][][] data;
        int [][][] demoData = {
            { { 1    }, { 2 }, { 3, 2 }, },
            { { 4, 3 }, { 5 }, { 6    }, },
        };

        try {
            if (args.length > 0) {
                data = Files.readAllLines(Paths.get(args[0])).stream()
                        .map(l -> l.split("(?<!^)[ ]+"))
                        .map(ea -> Arrays.stream(ea).map(e ->
                                        Arrays.stream(e.split("/")).map(
                                                f -> Integer.parseInt(f.trim())).mapToInt(Integer::intValue).toArray()
                                ).toArray(int[][]::new)
                        ).toArray(int[][][]::new);
            } else {
                data = demoData;
            }
        } catch (Exception e) {
            e.printStackTrace();
            data = demoData;
        }

        JRashunalMatrix m = new JRashunalMatrix(data);
        System.out.println("Input matrix:");
        System.out.println(m);

        try {
            JGaussFactorization factorization = RMatrixFFM.factor(data);

            System.out.println();
            System.out.println("PInverse:");
            System.out.println(factorization.pInverse);

            System.out.println();
            System.out.println("Lower:");
            System.out.println(factorization.lower);

            System.out.println();
            System.out.println("Diagonal:");
            System.out.println(factorization.diagonal);

            System.out.println();
            System.out.println("Upper:");
            System.out.println(factorization.upper);
        } catch (Throwable t) {
            System.err.println(t);
        }
    }
}
